-- Quranically V1.8: one precisely located, Hadith-backed Ayat al-Kursi dossier.
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('ayat-al-kursi-guide','ayat-al-kursi-guide','Ayat al-Kursi (2:255): Location, Meaning and Source References','آية الكرسي','Quran 2:255 with source-grounded context','quranic_themes','concept','Ayat al-Kursi is Qur’an 2:255 in Surah Al-Baqarah. It speaks of Allah’s unique divinity, life, knowledge and sustaining power. Sahih Muslim 810 reports a conversation about the verse’s standing, while Sahih al-Bukhari 5010 contains a reported benefit associated with reciting it before sleep. This is an introduction with exact source links, not an independent Tafsir.','Verified verse coordinate and scholarly-source pointers.','ayat al kursi,ayat ul kursi,ayat kursi,ayatul kursi,throne verse,where is ayat al kursi,where can i find ayat al kursi,ayah kursi,quran 2:255','Independent Tafsir review pending.','editorial_draft','published','96');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ayat-al-kursi-guide-s1','ayat-al-kursi-guide','Where to find the verse','scripture','Ayat al-Kursi is Surah Al-Baqarah 2:255. It is a single Qur’anic verse and can be read in full in the Quranically Qur’an Reader. This location is exact and should not be confused with a separate Surah named after the verse.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ayat-al-kursi-guide-s2','ayat-al-kursi-guide','The verse’s central themes','scripture','The verse describes Allah as the Living and Sustainer, denies that sleep or drowsiness overtakes Him, and speaks of His knowledge, authority and preservation of the heavens and earth. This is a short descriptive overview of themes present in the verse, not a full analysis of its Arabic vocabulary or theological schools.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ayat-al-kursi-guide-s3','ayat-al-kursi-guide','The virtue mentioned in Hadith','transmission','Sahih Muslim 810 records a conversation with Ubayy ibn Ka‘b concerning the verse’s status. Sahih al-Bukhari 5010 describes Abu Hurayrah’s encounter with a visitor and a statement about reciting the verse at bedtime, which was subsequently addressed by the Prophet ﷺ. Readers should inspect the complete Hadith accounts and their context rather than reducing them to invented guarantees.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ayat-al-kursi-guide-s4','ayat-al-kursi-guide','Interpretation and practice boundaries','methodology','Qur’an 2:255 may be read, studied and memorised, and the authenticated Hadith reports provide religious context. This dossier does not manufacture new promises of worldly outcomes, medical treatment or protection beyond what the cited reports say. A comprehensive Tafsir requires qualified scholarly review.','4');
